//! Pre-trained Generalized Geometric Language Model (`UR4GLM06`) Natural Prose Manifold,
//! CUDA-Trained Distributional Vocabulary Manifold (`GLM_TRAINED_VOCAB`),
//! CUDA-Trained Token-Level Autoregressive Lookahead Horizon Table (`GLM_TOKEN_HORIZONS`),
//! Hopf Fibration (`S^3 -> S^2 x U(1)`) Trajectory Predictor, 128-Bit VSA Hypervector Attention,
//! Algorithmic Puzzle Solvers, and Token-Level Geometric Autoregressive Decoder.
//!
//! Generated deterministically by the pure-Rust trainer `gpu/train_general_glm.rs` + CUDA kernel `gpu/general_glm.cu`.

use crate::{canonical_stem, is_stopword, q12_l1_distance, swar_hamming_distance, POINT_KEY_DIM};

/// Canonical weights version identifier trained by `gpu/general_glm.cu`.
pub const GLM_WEIGHTS_VERSION: &str = "UR4GLM06";
/// Whether these weights were optimized by the CUDA hardware kernel (`gpu/general_glm.cu`).
pub const GLM_CUDA_TRAINED: bool = true;

/// A CUDA-trained token-level lookahead horizon row (`RETAIN_LAMBDA_Q31` + 4D Hamilton quaternion + Base-17 4-Block Trunk + `/7` Geodesic Transition Edges).
#[derive(Debug, Clone, Copy)]
pub struct GlmTokenHorizon {
    /// Forward-decayed 8-lane Q12 lookahead horizon vector (`R4.IntegerStack.retainLambdaQ31`).
    pub horizon_q12: [i16; POINT_KEY_DIM],
    /// Forward-decayed 64-bit SWAR quaternion sign code.
    pub horizon_sign: u64,
    /// Base-17 4-Block Icosian root address (`0..83520`, `R4.DiscreteTrunk.pack4BlockRoots`).
    pub packed_4block: u32,
    /// Originating basin index (`0..164`).
    pub basin_id: u16,
    /// Paragraph section index (`0..4`).
    pub section_idx: u8,
    /// Sentence index within section (`0..N`).
    pub sentence_idx: u8,
    /// CUDA-trained primary `/7` geodesic continuation horizon index.
    pub next_horizon_id: u16,
    /// CUDA-trained alternate `/7` geodesic continuation horizon index.
    pub alt_horizon_id: u16,
    /// CUDA-trained geodesic transition energy along `next_horizon_id`.
    pub transition_energy: u32,
}

/// A CUDA-trained vocabulary stem coordinate row in `UR4GLM06` (derived strictly from training prose text).
/// Contains ONLY geometric coordinates (`Q12`, `SWAR` sign codes, `VSA` hypervectors, and IDF weight) — zero basin IDs.
#[derive(Debug, Clone, Copy)]
pub struct GlmVocabEntry {
    /// Canonical stem string (sorted lexicographically for O(log V) binary search).
    pub stem: &'static str,
    /// Primary trained 8-lane Q12 coordinate fiber.
    pub q12_coords: [i16; POINT_KEY_DIM],
    /// Secondary trained 8-lane Q12 coordinate fiber.
    pub alt_q12_coords: [i16; POINT_KEY_DIM],
    /// Primary trained 64-bit quaternion SWAR sign code.
    pub sign_code: u64,
    /// Secondary trained 64-bit quaternion SWAR sign code.
    pub alt_sign_code: u64,
    /// Trained 128-bit VSA hypervector signature (`[u64; 2]`).
    pub vsa_hv: [u64; 2],
    /// Integer inverse-document-frequency specificity weight in Q8 (`64..1024`).
    pub idf_weight: u16,
}

/// A pre-trained concept & natural-prose basin in the UOR-R4 Generalized Geometric Manifold (`UR4GLM06`).
#[derive(Debug, Clone, Copy)]
pub struct GlmConceptNode {
    /// Unique concept node index (`0..N`).
    pub id: u16,
    /// High-level knowledge domain label.
    pub domain: &'static str,
    /// Canonical concept title.
    pub title: &'static str,
    /// Primary lexical trigger keywords.
    pub keywords: &'static [&'static str],
    /// Multi-word canonical trigger phrases.
    pub phrases: &'static [&'static str],
    /// Trained 8-lane Q12 semantic coordinate vector.
    pub q12_coords: [i16; POINT_KEY_DIM],
    /// Trained 64-bit quaternion SWAR sign code.
    pub sign_code: u64,
    /// Hopf fibration S^2 Fubini-Study base coordinates in Q15.
    pub hopf_s2: [i16; 3],
    /// Hopf fibration U(1) fiber phase (cos, sin) in Q15.
    pub hopf_u1: [i16; 2],
    /// Condensed 128-bit VSA hypervector signature (`[u64; 2]`).
    pub vsa_hv: [u64; 2],
    /// Assigned 16-root E8 orbit index.
    pub e8_root: u8,
    /// Assigned 64-action Cl(0,6) Clifford carrier index.
    pub clifford_action: u8,
    /// Assigned 17-root Icosian Z[phi] lattice index (`R4.SpiralCoreFbs`).
    pub icosian_root: u8,
    /// Assigned 120-root H_4 600-cell polytope index.
    pub h4_root: u8,
    /// Opening natural prose paragraph (overview & framing).
    pub summary: &'static str,
    /// Second natural prose paragraph (historical / causal / mechanism depth).
    pub mechanism: &'static str,
    /// Third natural prose paragraph (principles, architecture, or cultural context).
    pub formal_principle: &'static str,
    /// Fourth natural prose paragraph (nuance, dynamics, or everyday life).
    pub tradeoffs: &'static str,
    /// Fifth natural prose paragraph (concrete illustration & synthesis).
    pub example: &'static str,
}

/// A classic logic, probability, or physics puzzle solved via exact step-by-step derivation.
#[derive(Debug, Clone, Copy)]
pub struct GlmLogicPuzzle {
    /// Canonical puzzle title.
    pub title: &'static str,
    /// Trigger keywords.
    pub keywords: &'static [&'static str],
    /// Multi-word trigger phrases.
    pub phrases: &'static [&'static str],
    /// Step-by-step formal solution in Markdown.
    pub solution_markdown: &'static str,
}

/// A fast conversational & common-sense Q&A pair (`mw-balp` + world facts).
#[derive(Debug, Clone, Copy)]
pub struct GlmConversationalQa {
    /// Trigger keywords.
    pub keywords: &'static [&'static str],
    /// Multi-word trigger phrases.
    pub phrases: &'static [&'static str],
    /// Natural conversational answer.
    pub answer: &'static str,
}

